def permuteThree(nums: list[int]) -> list[list[int]]:
    res = []
    def backtrack(curr, used):
        if len(curr) == len(nums):
            res.append(list(curr))
            return
        for i, val in enumerate(nums):
            if not used[i]:
                used[i] = True
                curr.append(val)
                backtrack(curr, used)
                curr.pop()
                used[i] = False
    backtrack([], [False] * len(nums))
    return sorted(res)

